sources.GesturePad.ets:
@Component
export struct GesturePad {
  @State offset: number = 0
  build() {
    Stack() { Text('Slide') }
    .gesture(
      PanGesture()
        .onActionUpdate((event: GestureEvent) => {
          this.offset = event.fingerList[0].localX
        })
    )
  }
}

